"""
NyayaMitra Controlled Document Generator ("Mera Document") Service
Provides deterministic template slot filling, schema validation, statutory citations,
and multi-format legal draft generation with mandatory disclaimers.
"""

from datetime import datetime, timezone
import hashlib
import uuid
from typing import Any, Optional
from pydantic import BaseModel, Field

# Statutory disclaimer required by law
MANDATORY_DISCLAIMER = (
    "DISCLAIMER: This document is a computer-generated draft generated by NyayaMitra "
    "(AI for Legal Assistance & Access). NyayaMitra is not a law firm and does not provide "
    "legal representation or legal advice. This draft is intended for informational and "
    "pro-se procedural assistance. You should review all facts carefully and consider "
    "consulting an advocate or your local District Legal Services Authority (DLSA) before formal submission."
)


class TemplateFieldSpec(BaseModel):
    name: str
    label: str
    description: str
    required: bool = True
    field_type: str = "text"  # text, date, number, list, textarea
    default: Optional[Any] = None
    example: Optional[str] = None


class TemplateDefinition(BaseModel):
    template_id: str
    title: str
    category: str
    statutory_act: str
    statutory_section: str
    description: str
    version: str = "1.0.0"
    fields: list[TemplateFieldSpec]


