class DocumentGeneratorService:
    """Handles deterministic validation, slot filling, and formatted draft rendering."""

    @classmethod
    def list_templates(cls) -> list[dict[str, Any]]:
        """Returns metadata and field requirements for all supported templates."""
        return [t.model_dump() for t in TEMPLATES.values()]

    @classmethod
    def get_template(cls, template_id: str) -> Optional[TemplateDefinition]:
        """Retrieves a specific template definition."""
        return TEMPLATES.get(template_id)

    @classmethod
    def validate_slots(
        cls, template_id: str, slots_data: dict[str, Any]
    ) -> dict[str, Any]:
        """
        Validates user-provided slots against template definition.
        Returns validation status, list of missing required fields, and cleaned data.
        """
        template = cls.get_template(template_id)
        if not template:
            return {
                "valid": False,
                "error": f"Unknown template ID '{template_id}'.",
                "missing_fields": [],
                "filled_fields": [],
            }

        missing_fields = []
        filled_fields = []
        cleaned_slots = {}

        for field in template.fields:
            val = slots_data.get(field.name)
            if val is not None and str(val).strip() != "":
                cleaned_slots[field.name] = val
                filled_fields.append(field.name)
            else:
                if field.required:
                    missing_fields.append({
                        "field_name": field.name,
                        "label": field.label,
                        "description": field.description,
                        "example": field.example,
                    })
                elif field.default is not None:
                    cleaned_slots[field.name] = field.default

        is_valid = len(missing_fields) == 0

        return {
            "valid": is_valid,
            "template_id": template_id,
            "template_title": template.title,
            "missing_fields": missing_fields,
            "filled_fields": filled_fields,
            "cleaned_slots": cleaned_slots,
        }

    @classmethod
    def generate_document(
        cls,
        template_id: str,
        slots_data: dict[str, Any],
        session_id: Optional[str] = None,
    ) -> dict[str, Any]:
        """
        Validates slots and deterministically renders the legal document.
        """
        validation = cls.validate_slots(template_id, slots_data)
        if not validation["valid"]:
            return {
                "success": False,
                "document_id": None,
                "error": "Validation failed: required fields are missing.",
                "missing_fields": validation["missing_fields"],
            }

        template = cls.get_template(template_id)
        if not template:
            return {
                "success": False,
                "document_id": None,
                "error": f"Template {template_id} not found.",
                "missing_fields": [],
            }

        cleaned = validation["cleaned_slots"]
        doc_id = str(uuid.uuid4())
        created_at = datetime.now(timezone.utc)
        date_str = created_at.strftime("%d-%m-%Y")

        # Deterministic slot filling based on template ID
        if template_id == "RTI_APPLICATION":
            content_md = cls._render_rti(cleaned, date_str)
        elif template_id == "CONSUMER_COMPLAINT":
            content_md = cls._render_consumer_complaint(cleaned, date_str)
        elif template_id == "LEGAL_NOTICE_CHEQUE_BOUNCE":
            content_md = cls._render_cheque_bounce_notice(cleaned, date_str)
        elif template_id == "RENT_DISPUTE_REPLY":
            content_md = cls._render_rent_reply(cleaned, date_str)
        else:
            return {"success": False, "error": f"No renderer for template {template_id}"}

        # Compute SHA-256 for audit integrity
        doc_hash = hashlib.sha256(content_md.encode("utf-8")).hexdigest()

        return {
            "success": True,
            "document_id": doc_id,
            "session_id": session_id,
            "template_id": template_id,
            "title": template.title,
            "statutory_basis": f"{template.statutory_act} ({template.statutory_section})",
            "markdown_content": content_md,
            "disclaimer": MANDATORY_DISCLAIMER,
            "slots_used": cleaned,
            "version": template.version,
            "sha256_hash": doc_hash,
            "created_at": created_at.isoformat(),
        }

    # --- Specific Template Renderers ---

    @staticmethod
    def _render_rti(slots: dict[str, Any], date_str: str) -> str:
        bpl_clause = (
            f"**Fee Exemption:** The applicant belongs to the Below Poverty Line (BPL) category "
            f"(Card No: {slots.get('bpl_card_number', 'N/A')}). Hence, no application fee is payable as per Section 7(5) of the RTI Act."
            if slots.get("is_bpl")
            else f"**Application Fee:** {slots.get('application_fee_details', 'Enclosed IPO/Fee Stamp of Rs. 10/-')}."
        )

        return f"""# APPLICATION UNDER SECTION 6(1) OF THE RIGHT TO INFORMATION ACT, 2005

**To,**  
The Public Information Officer (PIO) / Central Assistant PIO,  
**{slots.get('public_authority_name')}**,  
{slots.get('public_authority_address')}  

---

### 1. Applicant Particulars:
- **Full Name:** {slots.get('applicant_name')}  
- **Address for Correspondence:** {slots.get('applicant_address')}  
- **Contact Number / Email:** {slots.get('applicant_contact')}  
- **Citizenship:** Citizen of India  

---

### 2. Subject Matter of Information:
**{slots.get('subject_matter')}**

---

### 3. Particulars of Information Sought under Section 6(1):
The applicant hereby requests the following specific records, documents, and certified information:

{slots.get('particulars_of_information')}

*(Note: If any portion of the requested information falls under another Public Authority, kindly transfer this application within 5 days under Section 6(3) of the RTI Act, 2005 under intimation to the applicant.)*

---

### 4. Fee & BPL Status:
{bpl_clause}

---

### 5. Declaration:
I hereby state and declare that I am a citizen of India and that the information sought above is not exempt from disclosure under Section 8 or Section 9 of the Right to Information Act, 2005.

**Place:** {slots.get('place')}  
**Date:** {date_str}  

\n\n______________________________  
**Signature of Applicant**  
({slots.get('applicant_name')})

---
> *{MANDATORY_DISCLAIMER}*
"""

    @staticmethod
    def _render_consumer_complaint(slots: dict[str, Any], date_str: str) -> str:
        commission_dist = str(slots.get('commission_district') or '').upper()
        return f"""# BEFORE THE DISTRICT CONSUMER DISPUTES REDRESSAL COMMISSION
### AT: {commission_dist}

**CONSUMER COMPLAINT NO. _______ OF {date_str.split('-')[-1]}**  
*(Under Section 35 of the Consumer Protection Act, 2019)*

---

**IN THE MATTER OF:**

**{slots.get('complainant_name')}**  
Resident of: {slots.get('complainant_address')}  
*(Complainant)*  

**VERSUS**

**{slots.get('opposite_party_name')}**  
Having office at: {slots.get('opposite_party_address')}  
*(Opposite Party / Service Provider)*  

---

### MOST RESPECTFULLY SHOWETH:

1. **JURISDICTION & STATUS:**  
   The Complainant is a 'Consumer' within the meaning of Section 2(7) of the Consumer Protection Act, 2019, having purchased goods/services from the Opposite Party for personal use against valuable consideration. The cause of action arose within the territorial and pecuniary jurisdiction of this Hon'ble Commission.

2. **TRANSACTION DETAILS:**  
   On **{slots.get('transaction_date')}**, the Complainant purchased goods/availed services from the Opposite Party upon payment of **{slots.get('amount_paid')}** against valid invoice/receipt.

3. **FACTS AND DEFICIENCY IN SERVICE:**  
{slots.get('facts_of_case')}

4. **CAUSE OF ACTION:**  
   The cause of action arose when the Opposite Party failed to rectify the deficiency/defect despite written communications, and continues to subsist.

5. **PRAYER / RELIEF SOUGHT:**  
   In the premises aforesaid, the Complainant respectfully prays that this Hon'ble Commission may be pleased to:  
{slots.get('relief_claimed')}

---

### VERIFICATION
I, **{slots.get('complainant_name')}**, the Complainant above-named, do hereby verify that the contents of paragraphs 1 to 5 are true to my personal knowledge and belief, and nothing material has been concealed therefrom.

Verified at **{slots.get('place')}** on this **{date_str}**.

\n\n______________________________  
**Complainant in Person**  
({slots.get('complainant_name')})

---
> *{MANDATORY_DISCLAIMER}*
"""

    @staticmethod
    def _render_cheque_bounce_notice(slots: dict[str, Any], date_str: str) -> str:
        return f"""# STATUTORY DEMAND NOTICE UNDER SECTION 138 OF THE NEGOTIABLE INSTRUMENTS ACT, 1881

**(SENT VIA REGISTERED POST WITH ACKNOWLEDGEMENT DUE / SPEED POST / EMAIL)**

**Date:** {date_str}  
**Place:** {slots.get('place')}  

**To,**  
**{slots.get('recipient_name')}**  
{slots.get('recipient_address')}  

---

**SUBJECT:** Statutory Demand Notice under Section 138 read with Section 142 of the Negotiable Instruments Act, 1881, for dishonour of Cheque No. {slots.get('cheque_number')} for {slots.get('cheque_amount')}.

---

**Sir / Madam,**

Under instructions from and on behalf of my client / payee **{slots.get('sender_name')}**, residing/having office at {slots.get('sender_address')}, I/we hereby serve you with this statutory legal notice:

1. **LEGAL DEBT / LIABILITY:**  
   In discharge of your legally enforceable debt and liability towards my client, you had issued the following cheque:
   - **Cheque No:** {slots.get('cheque_number')}  
   - **Date of Cheque:** {slots.get('cheque_date')}  
   - **Amount:** {slots.get('cheque_amount')}  
   - **Drawee Bank:** {slots.get('bank_name')}  
   
   *Underlying Liability:* {slots.get('debt_liability_details')}

2. **PRESENTMENT & DISHONOUR:**  
   My client presented the said cheque for encashment through their bankers. However, the cheque was returned unpaid and dishonoured by the bank with the Return Memo dated **{slots.get('return_memo_date')}** with remarks **"{slots.get('return_reason', 'Funds Insufficient')}"**.

3. **STATUTORY 15-DAY DEMAND:**  
   You are hereby called upon to pay the cheque amount of **{slots.get('cheque_amount')}** to my client within **15 (fifteen) days** from the date of receipt of this notice.

4. **LEGAL CONSEQUENCES:**  
   Please note that in the event of your failure to make the aforesaid payment within 15 days of receipt of this notice, my client shall be constrained to initiate criminal proceedings against you under Section 138 of the Negotiable Instruments Act, 1881, as well as relevant provisions of Bharatiya Nyaya Sanhita, 2023, where you may be liable for imprisonment up to two years or fine which may extend to twice the amount of the cheque, or both.

Yours faithfully,

\n\n______________________________  
**{slots.get('sender_name')}**  
*(Payee / Authorized Signatory)*  
Address: {slots.get('sender_address')}

---
> *{MANDATORY_DISCLAIMER}*
"""

    @staticmethod
    def _render_rent_reply(slots: dict[str, Any], date_str: str) -> str:
        return f"""# FORMAL REPLY TO NOTICE OF EVICTION / RENT DISPUTE

**Date:** {date_str}  
**Place:** {slots.get('place')}  

**To,**  
**{slots.get('landlord_name')}**  
{slots.get('landlord_address')}  

---

**SUBJECT:** Reply to your notice dated {slots.get('notice_reference_date')} regarding tenancy of premises situated at {slots.get('tenant_address')}.

---

**Sir / Madam,**

I, **{slots.get('tenant_name')}**, the lawful tenant of the premises **{slots.get('tenant_address')}**, hereby reply to your notice dated **{slots.get('notice_reference_date')}** as under:

1. **TENANCY STATUS & COMPLIANCE:**  
   I have been residing/operating in the premises as a lawful tenant since **{slots.get('tenancy_commencement_date')}** at an agreed monthly rent of **{slots.get('monthly_rent')}**. You also hold a refundable security deposit of **{slots.get('security_deposit')}**.

2. **REBUTTAL OF ALLEGATIONS:**  
   The allegations and grounds set forth in your notice under reply are baseless, misleading, and legally untenable. In particular:  
{slots.get('tenant_rebuttal_points')}

3. **CALL UPON LANDLORD:**  
   You are requested to withdraw your wrongful and premature notice immediately and desist from causing any disturbance to my peaceful possession of the premises or attempting any unlawful eviction without due process of law.

Yours faithfully,

\n\n______________________________  
**{slots.get('tenant_name')}**  
*(Tenant)*  
Premises: {slots.get('tenant_address')}

---
> *{MANDATORY_DISCLAIMER}*
"""
